command:
// Propagation du poison (statut normalisé `poison` du registre FQ) : DAE
// ré-exécute cette macro à chaque FIN de tour de l'acteur affecté
// (flags.dae.macroRepeat = "endEveryTurn", args[0] === "each"). Chaque effet
// Poison se duplique UNE seule fois — la copie, vierge, se dupliquera au tour
// suivant : dégâts 1, 2, 3, 4… par tour (cumul quadratique).
if (args[0] !== "each") return;
const lastArg = args[args.length - 1];
if (lastArg?.turn !== "endTurn") return;
const moduleName = "fq-card-engine";
const effectActor = await fromUuid(lastArg.actorUuid);
const effect = effectActor?.effects?.get(lastArg.effectId);
if (!effect || effect.getFlag(moduleName, "hasReplicated")) return;
await effect.setFlag(moduleName, "hasReplicated", true);
const copy = effect.toObject();
delete copy._id;
foundry.utils.setProperty(copy, "flags." + moduleName + ".hasReplicated", false);
await effectActor.createEmbeddedDocuments("ActiveEffect", [copy]);
